function downloadCSV(tasks: Task[], s: State) { const rows = [['ID', 'Título', 'Quadro', 'Etapa', 'Prioridade', 'Prazo', 'Estimativa (h)', 'Resposta original'], ...tasks.map(t => ['VM-' + t.number, t.title, s.boards.find(b => b.id === t.boardId)?.name, s.boards.find(b => b.id === t.boardId)?.stages.find(x => x.id === t.stageId)?.name, t.priority, t.due, t.estimate, t.submission ? JSON.stringify(t.submission) : ''])]; const esc = (v: any) => '"' + String(v ?? '').replace(/^[=+@-]/, "'$&").replace(/"/g, '""') + '"'; const blob = new Blob(['\uFEFF' + rows.map(r => r.map(esc).join(';')).join('\r\n')], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'vamo-tarefas.csv'; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
